  (2, 'initial_settings', 'Phase 2: Initial Settings', 2, 'full,self', 'Theme, order settings, pricing tiers, payment gateway and terms, optional custom domain.'),
  (3, 'validate', 'Phase 3: Validate (10-order proof)', 3, 'full', 'Ten real past orders priced in Allmoxy and approved by the customer.'),
