  (5, 'go_live', 'Phase 5: Go-Live', 5, 'full,self', 'Soft launch with a few customers, ten live orders, then invite everyone.'),
  (6, 'grow', 'Phase 6: Grow', 6, 'full,self', 'Add-ons and quarterly reviews, ongoing.')
