INSERT INTO ob_role (role_key, name, description, sort_order) VALUES
  ('project_champion', 'Project Champion', 'One point of contact. Answers questions and signs off validation orders', 1),
  ('owner_manager', 'Owner / Manager', 'Final say on pricing, terms, and go-live. Approves the build', 2),
  ('sales', 'Sales', 'Quotes and bids, customer accounts, pricing tiers, and portal access', 3),
  ('customer_service', 'Customer Service', 'Enters and manages orders and answers customers', 4),
  ('designer_drafter', 'Designer / Drafter', 'Owns the design files (Cabinet Vision, Mozaik) that feed the Importer', 5),
  ('production_operations', 'Production / Operations', 'Runs the floor: partlists, labels, progress, and shipping', 6),
  ('catalog_owner', 'Catalog Owner', 'Keeps products, options, and pricing current after launch', 7),
  ('finance', 'Finance', 'Invoices, deposits, payments, and the accounting sync', 8),
  ('it_integrations', 'IT / Integrations', 'Logins, the payment gateway, and connections to other software', 9)
INSERT INTO ob_document_type (doc_key, name, description, sort_order) VALUES
  ('product_specifications', 'Product specifications', 'Box lines, door and finish options, modifications, accessories', 1),
  ('design_catalog_backup', 'Design software catalog backup', 'Full catalog from Cabinet Vision, Mozaik, Closet Pro, or similar', 2),
  ('pricing', 'Pricing and price adjustments', 'List pricing, plus tiers or multipliers by customer', 3),
  ('order_forms_past_orders', 'Current order forms and past orders', 'How customers order today; 20 to 30 past orders', 4),
  ('design_job_files', 'Design software job files', 'Example jobs so the import can be matched', 5),
  ('cutlist_cnc_samples', 'Cutlist and CNC file samples', 'Builds the partlist pages and the CNC exporter', 6),
  ('output_pages_exports', 'Output pages and exports you use today', 'Invoices, partlists, labels, and exports another system reads', 7),
  ('rules_exclusions', 'Rules and exclusions', 'Combinations not built or warrantied, size limits, disclaimers', 8),
  ('supplier_hardware_catalogs', 'Supplier and hardware catalogs', 'Hinges, slides, and outside components priced or offered', 9),
  ('brand_kit', 'Brand kit', 'Logos, fonts, imagery, form wording, product photos', 10)
INSERT INTO ob_training_session (session_key, phase_id, name, covers, audience, sort_order) VALUES
  ('welcome_platform_overview', 1, 'Welcome & Platform Overview', 'How an order flows from customer to production and invoicing', 'Owner / Manager', 1),
  ('allmoxy_terminology', 1, 'Allmoxy Terminology', 'Bids vs. orders, attributes, output pages, how products are built', 'Owner / Manager', 2),
  ('how_to_get_help', 1, 'How to Get Help', 'The knowledge base, your CSM, and how support works', 'Owner / Manager', 3),
  ('how_customers_order', 2, 'How Your Customers Order', 'The portal from the customer''s side, login to confirmation', 'Owner and Sales', 4),
  ('placing_managing_orders', 2, 'Placing & Managing Orders', 'Entering orders for customers, bids, and order statuses', 'Sales / Customer Service', 5),
  ('managing_customers', 2, 'Managing Your Customers', 'Customer accounts, pricing tiers, and portal access', 'Owner and Sales', 6),
  ('account_settings_review', 2, 'Account Settings Review', 'Permissions, branding, order workflow, and financial defaults', 'Owner / Manager', 7),
  ('full_customer_experience', 4, 'The Full Customer Experience', 'The whole team walks an order from portal to completion', 'Everyone', 8),
  ('automation_order_flow', 4, 'Automation & Order Flow', 'Every automated email, when it fires, how to change it', 'Owner and Customer Service', 9),
  ('production_shipping', 4, 'Production & Shipping', 'Receiving jobs, partlists and labels, marking progress, shipping', 'Production / Operations', 10),
  ('finance_payments', 4, 'Finance & Payments', 'Invoices, payments through the gateway, AR, accounting export', 'Finance / Owner', 11),
  ('catalog_maintenance', 4, 'Catalog Maintenance', 'Adding options, materials, and price changes without a ticket', 'Catalog Owner', 12),
  ('launch_preparation', 4, 'Launch Preparation', 'The launch checklist and soft-launch customers', 'Everyone', 13),
  ('first_live_order', 5, 'Your First Live Order', 'A real order from placement to invoice, every department', 'Everyone', 14),
  ('production_go_live_handoff', 5, 'Production Go-Live Handoff', 'The floor runs live jobs on its own', 'Production / Operations', 15),
  ('onboarding_your_customers', 5, 'Onboarding Your Customers', 'Inviting customers to the portal and their first order', 'Sales', 16),
  ('thirty_day_check_in', 5, '30-Day Check-In', 'What''s working, recurring questions, adjustments', 'Owner / Manager', 17),
  ('reporting_insights', 6, 'Reporting & Business Insights', 'Sales, throughput, AR aging, order history', 'Owner / Finance', 18),
  ('inventory_materials', 6, 'Inventory & Materials', 'Stock, allocation, purchase orders', 'Operations / Owner', 19),
  ('quarterly_business_review', 6, 'Quarterly Business Review', 'How Allmoxy is used and goals for next quarter', 'Owner / Manager', 20)
